wikiPage.body:
&lt;div class=&quot;presentation navmenu&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Acc&#232;s rapide aux tableaux r&#233;capitulatifs des dons&lt;a class=&quot;headeranchor&quot; id=&quot;Acc&#232;s_rapide_aux_tableaux_r&#233;capitulatifs_des_dons_0&quot; href=&quot;#Acc&#232;s_rapide_aux_tableaux_r&#233;capitulatifs_des_dons_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;table&gt;&lt;tr style=&quot;vertical-align: top; text-align: left&quot;&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Dons.html&quot; title=&quot;Tableau r&#233;capitulatif des dons&quot;&gt;Dons g&#233;n&#233;raux&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Dons-Mythiques.html&quot; title=&quot;Dons mythiques&quot;&gt;Dons mythiques&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-Daudace-Et-De-Panache.html&quot; title=&quot;Dons d&amp;#39;audace et de panache&quot;&gt;Dons d&#39;audace et de panache&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Combat.html&quot; title=&quot;Dons de combat&quot;&gt;Dons de combat&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Cr&#233;ation-Dobjets.html&quot; title=&quot;Dons de cr&#233;ation d&amp;#39;objets&quot;&gt;Dons de cr&#233;ation d&#39;objets&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Critique.html&quot; title=&quot;Dons de critique&quot;&gt;Dons de critique&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-D&#233;cole.html&quot; title=&quot;Dons d&amp;#39;&#233;cole&quot;&gt;Dons d&#39;&#233;cole&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-D&#233;quipe.html&quot; title=&quot;Dons d&amp;#39;&#233;quipe&quot;&gt;Dons d&#39;&#233;quipe&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Ma&#238;trise-Darme.html&quot; title=&quot;Dons de ma&#238;trise d&amp;#39;arme&quot;&gt;Dons de ma&#238;trise d&#39;arme&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Ma&#238;trise-Darmure.html&quot; title=&quot;Dons de ma&#238;trise d&amp;#39;armure&quot;&gt;d&#39;armure&lt;/a&gt;,&lt;br /&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Ma&#238;trise-De-Bouclier.html&quot; title=&quot;Dons de ma&#238;trise de bouclier&quot;&gt;de bouclier&lt;/a&gt;, et &lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Ma&#238;trise-Dobjets.html&quot; title=&quot;Dons de ma&#238;trise d&amp;#39;objet&quot;&gt;d&#39;objet&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Mal&#233;fice-Sanglant.html&quot; title=&quot;Dons de mal&#233;fice sanglant&quot;&gt;Dons de mal&#233;fice sanglant&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-M&#233;tamagie.html&quot; title=&quot;Dons de m&#233;tamagie&quot;&gt;Dons de m&#233;tamagie&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Regard.html&quot; title=&quot;dons de regard&quot;&gt;Dons de regard&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-R&#233;ussite.html&quot; title=&quot;Dons de r&#233;ussite&quot;&gt;Dons de r&#233;ussite&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Spectacle.html&quot; title=&quot;Dons de spectacle&quot;&gt;Dons de spectacle&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-Dalignement.html&quot; title=&quot;Dons d&amp;#39;alignement&quot;&gt;Dons d&#39;alignement (PU)&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-Dhistoire.html&quot; title=&quot;Dons d&amp;#39;histoire&quot;&gt;Dons d&#39;histoire (GC)&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-&#201;sot&#233;riques.html&quot; title=&quot;Dons &#233;sot&#233;riques&quot;&gt;Dons &#233;sot&#233;riques (PU)&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;&lt;ul&gt;
    &lt;li&gt;R&#232;gles g&#233;n&#233;rales&lt;/li&gt;
    &lt;ul&gt;
        &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons.html#DESCRIPTION&quot; title=&quot;Les dons&quot;&gt;format&lt;/a&gt;&lt;/li&gt;
        &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons.html#TYPES&quot; title=&quot;Les dons&quot;&gt;types de dons&lt;/a&gt;&lt;/li&gt;
    &lt;/ul&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;&lt;script&gt;
$(function () {
  $(&quot;tr.donpr&#233;requis0, tr.donpr&#233;requis1, tr.donpr&#233;requis2&quot;).hide();
  $(&quot;tr.donprincipal&quot;).bind(&quot;click&quot;, togglePrereq);
  $(&quot;tr.donpr&#233;requis0&quot;).bind(&quot;click&quot;, togglePrereq0);
  $(&quot;tr.donpr&#233;requis1&quot;).bind(&quot;click&quot;, togglePrereq1);
  $(&quot;tr.donprincipal&quot;).each(addPrereqIconIfNeeded);
  $(&quot;tr.donpr&#233;requis0&quot;).each(addPrereqIconIfNeeded0);
  $(&quot;tr.donpr&#233;requis1&quot;).each(addPrereqIconIfNeeded1);
  $(&quot;tr.donpr&#233;requis2&quot;).each(addPrereqIconIfNeeded2);
});
function togglePrereq() {
    let nodeImg = $(this).find(&quot;img&quot;);
      if (nodeImg.attr(&quot;src&quot;) == &quot;/Forum/themes/v2/sort_down.gif&quot;) {
            nodeImg.attr(&quot;src&quot;, &quot;/Forum/themes/v2/sort_up.gif&quot;);
      } else {
            nodeImg.attr(&quot;src&quot;, &quot;/Forum/themes/v2/sort_down.gif&quot;);
      };
    let node = $(this).next();
    while (node.length &gt; 0 &amp;&amp; node.hasClass(&quot;donpr&#233;requis0&quot;) || node.hasClass(&quot;donpr&#233;requis1&quot;) || node.hasClass(&quot;donpr&#233;requis2&quot;)) {
      node.toggle();
      if (node.hasClass(&quot;donpr&#233;requis1&quot;) || node.hasClass(&quot;donpr&#233;requis2&quot;)) {
            node.toggle();
      };
      node = node.next();
    }
}
function togglePrereq0() {
    let nodeImg = $(this).find(&quot;img&quot;);
      if (nodeImg.attr(&quot;src&quot;) == &quot;/Forum/themes/v2/sort_down.gif&quot;) {
            nodeImg.attr(&quot;src&quot;, &quot;/Forum/themes/v2/sort_up.gif&quot;);
      } else {
            nodeImg.attr(&quot;src&quot;, &quot;/Forum/themes/v2/sort_down.gif&quot;);
      };
    let node = $(this).next();
    while (node.length &gt; 0 &amp;&amp; node.hasClass(&quot;donpr&#233;requis1&quot;) || node.hasClass(&quot;donpr&#233;requis2&quot;)) {
      node.toggle();
      if (node.hasClass(&quot;donpr&#233;requis2&quot;)) {
            node.toggle();
      };
      node = node.next();
    }
}
function togglePrereq1() {
    let nodeImg = $(this).find(&quot;img&quot;);
      if (nodeImg.attr(&quot;src&quot;) == &quot;/Forum/themes/v2/sort_down.gif&quot;) {
            nodeImg.attr(&quot;src&quot;, &quot;/Forum/themes/v2/sort_up.gif&quot;);
      } else {
            nodeImg.attr(&quot;src&quot;, &quot;/Forum/themes/v2/sort_down.gif&quot;);
      };
    let node = $(this).next();
    while (node.length &gt; 0 &amp;&amp; node.hasClass(&quot;donpr&#233;requis2&quot;)) {
      node.toggle();
      node = node.next();
    }
}
function addPrereqIconIfNeeded() {
	let next = $(this).next();
	if (next.length &gt; 0 &amp;&amp; next.hasClass(&quot;donpr&#233;requis0&quot;)) {
	  let icon = document.createElement(&quot;img&quot;);
	  icon.src = &quot;/Forum/themes/v2/sort_down.gif&quot;;
	  icon.style = &quot;float:right;margin-top: 3px;&quot;;
	  icon.title = &quot;Cliquez pour afficher les dons qui d&#233;coulent de celui-ci.&quot;;
	  $(this).children(&quot;td&quot;).first().append($(icon));
	}
}
function addPrereqIconIfNeeded0() {
	let next = $(this).next();
	if (next.length &gt; 0 &amp;&amp; next.hasClass(&quot;donpr&#233;requis1&quot;)) {
	  let icon = document.createElement(&quot;img&quot;);
	  icon.src = &quot;/Forum/themes/v2/sort_down.gif&quot;;
	  icon.style = &quot;float:right;margin-top: 3px;&quot;;
	  icon.title = &quot;Cliquez pour afficher les dons qui d&#233;coulent de celui-ci.&quot;;
	  $(this).children(&quot;td&quot;).first().append($(icon));
	}
}
function addPrereqIconIfNeeded1() {
	let next = $(this).next();
	if (next.length &gt; 0 &amp;&amp; next.hasClass(&quot;donpr&#233;requis2&quot;)) {
	  let icon = document.createElement(&quot;img&quot;);
	  icon.src = &quot;/Forum/themes/v2/sort_down.gif&quot;;
	  icon.style = &quot;float:right;margin-top: 3px;&quot;;
	  icon.title = &quot;Cliquez pour afficher les dons qui d&#233;coulent de celui-ci.&quot;;
	  $(this).children(&quot;td&quot;).first().append($(icon));
	}
	if (next.length &gt; 0 &amp;&amp; next.hasClass(&quot;donpr&#233;requis0&quot;)) {
	  $(this).children(&quot;td&quot;).css(&quot;border-bottom&quot;, &quot;1px solid black&quot;);
	}
}
function addPrereqIconIfNeeded2() {
	if (next.length &gt; 0 &amp;&amp; next.hasClass(&quot;donpr&#233;requis0&quot;) || next.hasClass(&quot;donpr&#233;requis1&quot;)) {
	  $(this).children(&quot;td&quot;).css(&quot;border-bottom&quot;, &quot;1px solid black&quot;);
	}
}
&lt;/script&gt;&lt;div style=&quot;float:right; padding-left: 6px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Manuel-Des-Joueurs-(Dons-Et-Comp&#233;tences).html#25&quot; title=&quot;FAQ du Manuel des joueurs, section dons et comp&#233;tences&quot;&gt;→&lt;/a&gt; M&#233;tamagie : Le sort est consid&#233;r&#233; comme &#233;tant de quel niveau dans le cadre des DD de concentration, du souvenir magique du magus, ou de la perle de thaumaturge ?&lt;/i&gt;&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;Le sort compte comme &#233;tant du niveau de l’emplacement n&#233;cessaire pour le lancer.&lt;br /&gt;&lt;br /&gt;Par exemple, un sort de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mains-Br&#251;lantes.html&quot; title=&quot;Mains br&#251;lantes&quot;&gt;mains br&#251;lantes&lt;/a&gt;&lt;/i&gt; &#224; &lt;a class=&quot;pagelink&quot; href=&quot;Extension-Deffet.html&quot; title=&quot;Extension d&amp;#39;effet&quot;&gt;extension d’effet&lt;/a&gt; utilise un emplacement de 3e niveau, et compte donc comme un sort de 3e niveau dans le cadre des tests de concentration, du &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#SOUVENIRMAGIQUE&quot; title=&quot;Le magus&quot;&gt;souvenir magique&lt;/a&gt; du magus ou d’une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Perle-De-Thaumaturge.html&quot; title=&quot;Perle de thaumaturge&quot;&gt;perle de thaumaturge&lt;/a&gt;&lt;/i&gt;.&lt;br /&gt;&lt;br /&gt;En g&#233;n&#233;ral, on utilise le niveau du sort (normal, moins &#233;lev&#233;) ou le niveau de l’emplacement d&#233;pens&#233; (plus &#233;lev&#233;), suivant le plus d&#233;savantageux pour le lanceur de sorts. Les avantages du &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons.html#DONMETAMAGIE&quot; title=&quot;Les dons&quot;&gt;don de m&#233;tamagie&lt;/a&gt;&lt;/u&gt; sont explicit&#233;s dans la section Avantages du don, et un niveau d’emplacement de sort augment&#233; est un d&#233;savantage.&lt;br /&gt;&lt;br /&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Augmentation-Dintensit&#233;.html&quot; title=&quot;Augmentation d&amp;#39;intensit&#233;&quot;&gt;Augmentation d’intensit&#233;&lt;/a&gt; est en fait le seul don de m&#233;tamagie qui fait de l’utilisation d’un emplacement de niveau plus &#233;lev&#233; un avantage plut&#244;t qu’un d&#233;savantage.
&lt;hr&gt;
&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Manuel-Des-Joueurs-(Dons-Et-Comp&#233;tences).html#26&quot; title=&quot;FAQ du Manuel des joueurs, section dons et comp&#233;tences&quot;&gt;→&lt;/a&gt; M&#233;tamagie : Puis-je utiliser un don de m&#233;tamagie pour modifier un pouvoir magique ?&lt;/i&gt;&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;Non. Les &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons.html#DONMETAMAGIE&quot; title=&quot;Les dons&quot;&gt;dons de m&#233;tamagie&lt;/a&gt;&lt;/u&gt; pr&#233;cisent qu’ils n’affectent que les sorts, et pas les &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Magiques-(Capacit&#233;).html&quot; title=&quot;Pouvoirs magiques (Mag)&quot;&gt;pouvoirs magiques&lt;/a&gt;. De m&#234;me, les pouvoirs magiques n’ont pas d’emplacements de sort, donc il serait impossible d’ajuster l’emplacement de sort effectif d’un pouvoir magique.
&lt;hr&gt;
&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Manuel-Des-Joueurs-(&#201;quipement-Et-Objets-Magiques).html#26&quot; title=&quot;FAQ du Manuel des joueurs, section &#233;quipement et objets magiques&quot;&gt;→&lt;/a&gt; M&#233;tamagie : Lorsque je lance un sort depuis un parchemin, une baguette, ou un b&#226;ton, puis-je appliquer un ou plusieurs dons de m&#233;tamagie &#224; ce sort ?&lt;/i&gt;&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;Non. &lt;i&gt;(Retour &#224; la &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons.html#DONMETAMAGIE&quot; title=&quot;Les dons&quot;&gt;r&#232;gle&lt;/a&gt;&lt;/u&gt;)&lt;/i&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:50px; cursor:pointer&quot; src=&quot;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&quot; title=&quot;Cliquez pour afficher/cacher une FAQ officielle relative &#224; ce texte&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
var cible = this.parentNode.previousSibling.previousSibling;
if (cible.style.display==&#39;none&#39;) {
  $(cible).show(&#39;slide&#39;);
  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqalt1.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&#39;;&quot; /&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;&#192; mesure que les connaissances magiques d’un lanceur de sorts augmentent, il peut apprendre &#224; jeter des sorts &#224; l’aide de m&#233;thodes l&#233;g&#232;rement diff&#233;rentes de celles qu’on lui a enseign&#233;es. Pr&#233;parer et lancer les sorts ainsi pr&#233;sente davantage de difficult&#233;s que les m&#233;thodes classiques, mais les dons de m&#233;tamagie permettent de repousser ses limites. Les dons de m&#233;tamagie n&#39;affectent pas les pouvoirs magiques.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Magiciens et pratiquants de la magie divine.&lt;/b&gt; Les magiciens et les pratiquants de la magie divine doivent pr&#233;parer leurs sorts &#224; l’avance. C’est &#224; ce moment qu’ils d&#233;cident s’ils souhaitent les pr&#233;parer en les modifiant gr&#226;ce &#224; des dons de m&#233;tamagie (ce qui les oblige &#224; utiliser des &lt;a class=&quot;pagelink&quot; href=&quot;Emplacement-De-Sort.html&quot; title=&quot;emplacement de sort&quot;&gt;emplacements de sorts&lt;/a&gt; de niveau sup&#233;rieur).&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Bardes et ensorceleurs.&lt;/b&gt; En revanche, les bardes et les ensorceleurs choisissent leurs sorts quand ils les jettent. Ils d&#233;cident donc au dernier moment s’ils souhaitent augmenter la puissance de leur sort &#224; l’aide d’un don de m&#233;tamagie. Pour eux aussi, le sort requiert un &lt;a class=&quot;pagelink&quot; href=&quot;Emplacement-De-Sort.html&quot; title=&quot;emplacement de sort&quot;&gt;emplacement de niveau sup&#233;rieur&lt;/a&gt;. Comme le personnage ne pr&#233;pare pas le sort &#224; l’avance, il est oblig&#233; de rallonger le &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts.html#TEMPSDINCANTATION&quot; title=&quot;Pr&#233;sentation des sorts&quot;&gt;temps d’incantation&lt;/a&gt; afin d’int&#233;grer le don de m&#233;tamagie au sort qu’il r&#233;cite. Si le temps d’incantation normal du sort &#233;quivaut &#224; une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, un barde ou ensorceleur aura besoin d’une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Complexe.html&quot; title=&quot;Action complexe&quot;&gt;action complexe&lt;/a&gt; pour le lancer en tant que sort de m&#233;tamagie (ce qui ne correspond pas &#224; un temps d’incantation d’un round entier). Les sorts modifi&#233;s par le don de m&#233;tamagie &lt;a class=&quot;pagelink&quot; href=&quot;Incantation-Rapide.html&quot; title=&quot;Incantation rapide&quot;&gt;Incantation rapide&lt;/a&gt; repr&#233;sentent la seule exception &#224; la r&#232;gle et se lancent de la fa&#231;on d&#233;termin&#233;e par ce don.&lt;br /&gt;&lt;br /&gt;Pour les sorts &#224; incantation plus longue, il faut rajouter une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Complexe.html&quot; title=&quot;Action complexe&quot;&gt;action complexe&lt;/a&gt; au temps donn&#233;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Sorts spontan&#233;s et dons de m&#233;tamagie.&lt;/b&gt; Les pr&#234;tres et les druides lan&#231;ant spontan&#233;ment des sorts de soins, de blessure ou de convocation d’alli&#233;s naturels peuvent &#233;galement utiliser la m&#233;tamagie. Le temps d’incantation augmente aussi dans ce cas. Si le temps d’incantation normal du sort est d’une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, sa version m&#233;tamagique n&#233;cessite une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Complexe.html&quot; title=&quot;Action complexe&quot;&gt;action complexe&lt;/a&gt;. Pour les sorts &#224; incantation plus longue, il faut rajouter une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Complexe.html&quot; title=&quot;Action complexe&quot;&gt;action complexe&lt;/a&gt; au temps indiqu&#233;. Les sorts modifi&#233;s par le don de m&#233;tamagie &lt;a class=&quot;pagelink&quot; href=&quot;Incantation-Rapide.html&quot; title=&quot;Incantation rapide&quot;&gt;Incantation rapide&lt;/a&gt; repr&#233;sentent la seule exception &#224; la r&#232;gle et se lancent comme une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Effet des dons de m&#233;tamagie sur un sort.&lt;/b&gt; Un sort de m&#233;tamagie fonctionne selon son &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Niveau.html&quot; title=&quot;Niveau de sort&quot;&gt;niveau&lt;/a&gt; d’origine, bien qu&#39;il soit pr&#233;par&#233; et lanc&#233; comme un sort de niveau sup&#233;rieur. Le &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jet de sauvegarde&lt;/a&gt; ne change pas &#224; moins que la description du don n’indique le contraire.&lt;br /&gt;&lt;br /&gt;Les changements indiqu&#233;s fonctionnent uniquement sur les sorts jet&#233;s directement par le personnage. Il est impossible d’utiliser un don de m&#233;tamagie sur un sort lanc&#233; via un parchemin, une baguette ou un autre objet magique.&lt;br /&gt;&lt;br /&gt;Les dons de m&#233;tamagie qui dispensent de composantes n’emp&#234;chent pas les &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;attaque d&amp;#39;opportunit&#233;&quot;&gt;attaques d’opportunit&#233;&lt;/a&gt; provoqu&#233;es par l’incantation d’un sort dans un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Espacecontrole.html&quot; title=&quot;espace contr&#244;l&#233;&quot;&gt;espace contr&#244;l&#233;&lt;/a&gt; par un adversaire. Cependant, un sort &#224; incantation rapide (modifi&#233; par le don &lt;a class=&quot;pagelink&quot; href=&quot;Incantation-Rapide.html&quot; title=&quot;Incantation rapide&quot;&gt;Incantation rapide&lt;/a&gt;) ne provoque pas d’&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;attaque d&amp;#39;opportunit&#233;&quot;&gt;attaque d’opportunit&#233;&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;Les dons de m&#233;tamagie ne peuvent pas &#234;tre utilis&#233;s pour tous les sorts. Consultez la description de chaque don pour conna&#238;tre les sorts qu’il ne peut pas affecter.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Dons de m&#233;tamagie multiples sur un m&#234;me sort.&lt;/b&gt; On peut multiplier les dons de m&#233;tamagie utilis&#233;s sur un sort, mais l’augmentation de niveau est cumulative. Il est impossible d’appliquer deux fois le m&#234;me don de m&#233;tamagie &#224; un sort donn&#233;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Objets magiques et dons de m&#233;tamagie.&lt;/b&gt; Avec le don de cr&#233;ation d’objets idoine, on peut stocker un sort de m&#233;tamagie dans une potion, un parchemin ou une baguette. La limite de niveau concernant les baguettes et les potions s’applique au niveau du sort apr&#232;s modification (apr&#232;s l’application du don de m&#233;tamagie). Il n’est pas n&#233;cessaire d’avoir le don de m&#233;tamagie correspondant pour activer un objet de ce type.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Contresorts et dons de m&#233;tamagie.&lt;/b&gt; Qu’un sort ait &#233;t&#233; modifi&#233; ou non par m&#233;tamagie, il est toujours vuln&#233;rable aux contresorts, et reste lui-m&#234;me un &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Contresort.html&quot; title=&quot;contresort&quot;&gt;contresort&lt;/a&gt; efficace.&lt;br /&gt;&lt;br /&gt;&lt;center&gt;
&lt;table CLASS=&quot;tablo toutgauche&quot;&gt;&lt;caption&gt;Tableau r&#233;capitulatif des dons de m&#233;tamagie&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;20%&quot;&gt;Dons&lt;/td&gt;&lt;td WIDTH=&quot;3%&quot;&gt;Src&lt;/td&gt;&lt;td WIDTH=&quot;22%&quot;&gt;Conditions&lt;/td&gt;&lt;td WIDTH=&quot;45%&quot;&gt;Avantages&lt;/td&gt;&lt;td WIDTH=&quot;10%&quot;&gt;Mod. niveau&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Augmentation-Dintensit&#233;.html&quot; title=&quot;Augmentation d&amp;#39;intensit&#233;&quot;&gt;Augmentation d&#39;intensit&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Le sort est consid&#233;r&#233; comme d&#39;un niveau sup&#233;rieur&lt;/td&gt;&lt;td&gt;Voir texte&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cho-Magique.html&quot; title=&quot;&#201;cho magique&quot;&gt;&#201;cho magique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Possibilit&#233; de relancer le sort&lt;/td&gt;&lt;td&gt;+3&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;treinte-De-Lombre.html&quot; title=&quot;&#201;treinte de l&amp;#39;ombre&quot;&gt;&#201;treinte de l&#39;ombre&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MMI&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-T&#233;n&#233;breux.html&quot; title=&quot;Sort t&#233;n&#233;breux&quot;&gt;Sort t&#233;n&#233;breux&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Sort-Umbral.html&quot; title=&quot;Sort umbral&quot;&gt;Sort umbral&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Les sorts du registre de l&#39;obscurit&#233; enchev&#234;trent ceux qui se trouvent dans la zone d&#39;effet du sort&lt;/td&gt;&lt;td&gt;+1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Extension-Deffet.html&quot; title=&quot;Extension d&amp;#39;effet&quot;&gt;Extension d&#39;effet&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Augmente les variables des sorts de 50%&lt;/td&gt;&lt;td&gt;+2&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Extension-De-Dur&#233;e.html&quot; title=&quot;Extension de dur&#233;e&quot;&gt;Extension de dur&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Double la dur&#233;e des sorts&lt;/td&gt;&lt;td&gt;+1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Extension-De-Port&#233;e.html&quot; title=&quot;Extension de port&#233;e&quot;&gt;Extension de port&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Double la port&#233;e des sorts&lt;/td&gt;&lt;td&gt;+1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Extension-De-Zone-Deffet.html&quot; title=&quot;Extension de zone d&amp;#39;effet&quot;&gt;Extension de zone d&#39;effet&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Double la zone d&#39;effet des sorts&lt;/td&gt;&lt;td&gt;+3&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Illusion-Mena&#231;ante.html&quot; title=&quot;Illusion mena&#231;ante&quot;&gt;Illusion mena&#231;ante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cole-Renforc&#233;e.html&quot; title=&quot;&#201;cole renforc&#233;e&quot;&gt;&#201;cole renforc&#233;e&lt;/a&gt; (illusion), &lt;a class=&quot;pagelink&quot; href=&quot;Gnome.html&quot; title=&quot;Les gnomes&quot;&gt;gnome&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Fait croire aux adversaires que les illusions du personnage sont de vraies menaces&lt;/td&gt;&lt;td&gt;+1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Incantation-Rapide.html&quot; title=&quot;Incantation rapide&quot;&gt;Incantation rapide&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Lance le sort par une action rapide&lt;/td&gt;&lt;td&gt;+4&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Incantation-Silencieuse.html&quot; title=&quot;Incantation silencieuse&quot;&gt;Incantation silencieuse&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Le sort n&#39;a plus de composante verbale&lt;/td&gt;&lt;td&gt;+1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Incantation-Statique.html&quot; title=&quot;Incantation statique&quot;&gt;Incantation statique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Le sort n&#39;a plus de composante gestuelle&lt;/td&gt;&lt;td&gt;+1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Quintessence-Des-Sorts.html&quot; title=&quot;Quintessence des sorts&quot;&gt;Quintessence des sorts&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Les variables du sort sont au maximum&lt;/td&gt;&lt;td&gt;+3&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sale-Coup-Magique.html&quot; title=&quot;Sale coup magique&quot;&gt;Sale coup magique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;DTT&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Capacit&#233; &#224; lancer des sorts de niveau 1, alignement Chaotique Neutre, suivant de la &lt;a class=&quot;pagelink&quot; href=&quot;../Golarion/Calistria.html&quot; title=&quot;Calistria&quot;&gt;d&#233;esse-elfe aux trois visages&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Un sort d&#39;enchantement peut appliquer les effets d&#39;un sale coup&lt;/td&gt;&lt;td&gt;+1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-&#192;-Rebonds.html&quot; title=&quot;Sort &#224; rebonds&quot;&gt;Sort &#224; rebonds&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Redirige un sort qui n&#39;a pas d&#39;effet sur la premi&#232;re cible&lt;/td&gt;&lt;td&gt;+1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-Ascendant.html&quot; title=&quot;Sort ascendant&quot;&gt;Sort ascendant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Imite la version mythique d&#39;un sort&lt;/td&gt;&lt;td&gt;+5&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-Br&#251;lant.html&quot; title=&quot;Sort br&#251;lant&quot;&gt;Sort br&#251;lant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Les sorts du registre de l&#39;acide et du feu infligent des d&#233;g&#226;ts suppl&#233;mentaires&lt;/td&gt;&lt;td&gt;+2&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-Brusque.html&quot; title=&quot;Sort brusque&quot;&gt;Sort brusque&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;MTT&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;Dex&quot;&gt;Dex&lt;/a&gt; 13&lt;/td&gt;&lt;td&gt;Une vitesse de d&#233;placement conf&#233;r&#233;e par le sort augmente de +3m&lt;/td&gt;&lt;td&gt;+0&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-Concentr&#233;.html&quot; title=&quot;Sort concentr&#233;&quot;&gt;Sort concentr&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Augmente le DD des jets de sauvegarde d&#39;une des cibles du sort&lt;/td&gt;&lt;td&gt;+1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-&#201;blouissant.html&quot; title=&quot;Sort &#233;blouissant&quot;&gt;Sort &#233;blouissant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Les sorts du registre du feu, de la lumi&#232;re ou de l&#39;&#233;lectricit&#233; &#233;blouissent leur cible&lt;/td&gt;&lt;td&gt;+1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-&#201;coeurant.html&quot; title=&quot;Sort &#233;cœurant&quot;&gt;Sort &#233;coeurant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Rend fi&#233;vreuses les cr&#233;atures bless&#233;es&lt;/td&gt;&lt;td&gt;+2&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-Ectoplasmique.html&quot; title=&quot;Sort ectoplasmique&quot;&gt;Sort ectoplasmique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Les cr&#233;atures intangibles ou &#233;th&#233;r&#233;es subissent les pleins effets du sort&lt;/td&gt;&lt;td&gt;+1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&